import catalog from './catalog.json';
import {Theme} from '../../../core/services/theme.service';

/** A muscle or a region of the 3D model (generated by tools/muscle-model). */
export interface MuscleModelEntry {
  parts: string[];
  view: string;
  zoom: number;
  center: number[];
  size: number;
}

const BASE = '/muscle-model';
const MUSCLES: Record<string, MuscleModelEntry> = catalog.muscles;
const REGIONS: Record<string, MuscleModelEntry> = catalog.regions;

export const MODEL_URL = `${BASE}/${catalog.model}`;
export const DRACO_PATH = `${BASE}/draco/`;
export const LICENSE_URL = `${BASE}/LICENSE.txt`;

/** The model entry of a muscle; undefined for a muscle added to the catalog before the model was regenerated. */
export function muscleModelEntry(code: string | null | undefined): MuscleModelEntry | undefined {
  return code && Object.hasOwn(MUSCLES, code) ? MUSCLES[code] : undefined;
}

export function muscleImageUrl(code: string | null | undefined, theme: Theme): string | undefined {
  return muscleModelEntry(code) ? `${BASE}/images/${theme}/${code}.webp` : undefined;
}

export function muscleThumbUrl(code: string | null | undefined, theme: Theme): string | undefined {
  return muscleModelEntry(code) ? `${BASE}/thumbs/${theme}/${code}.webp` : undefined;
}

/** A region of the catalog home (LEGS, BACK...), every muscle of the region in red. */
export function muscleRegionEntry(region: string | null | undefined): MuscleModelEntry | undefined {
  const key = regionKey(region);
  return key ? REGIONS[key] : undefined;
}

export function muscleRegionUrl(region: string | null | undefined, theme: Theme): string | undefined {
  const key = regionKey(region);
  return key ? `${BASE}/regions/${theme}/${key}.webp` : undefined;
}

function regionKey(region: string | null | undefined): string | undefined {
  const key = region?.toLowerCase();
  return key && Object.hasOwn(REGIONS, key) ? key : undefined;
}

/** False without WebGL 2 or in data saver mode: the page then keeps the image. */
export function canShow3d(): boolean {
  if (typeof WebGL2RenderingContext === 'undefined') return false;
  const connection = (navigator as Navigator & {connection?: {saveData?: boolean}}).connection;
  if (connection?.saveData) return false;
  try {
    const context = document.createElement('canvas').getContext('webgl2');
    context?.getExtension('WEBGL_lose_context')?.loseContext();
    return !!context;
  } catch {
    return false;
  }
}
